def token(name: str, theme: str = "light") -> str:
    """Literal token value. Raises on an unknown name rather than silently
    falling back — an off-palette colour should break the build."""
    table = DARK if theme == "dark" else LIGHT
    return table[name]


def rgb(name: str, theme: str = "light"):
    """Token as a 0..1 RGB tuple, for ReportLab / matplotlib."""
    h = token(name, theme).lstrip("#")
    if len(h) != 6:
        raise ValueError(f"{name} is not a plain hex colour: {h!r}")
    return tuple(int(h[i:i + 2], 16) / 255 for i in (0, 2, 4))
